// Spike Phase 1: prove @langchain/langgraph imports, compiles, and runs an
// interrupt -> resume cycle on the Cloudflare Workers (workerd) runtime.
// No Durable Object yet — just MemorySaver in-process, single request.
import {
  StateGraph,
  Annotation,
  MemorySaver,
  interrupt,
  Command,
} from "@langchain/langgraph";

const SpikeState = Annotation.Root({
  count: Annotation<number>({ reducer: (_, b) => b, default: () => 0 }),
  log: Annotation<string[]>({ reducer: (a, b) => a.concat(b), default: () => [] }),
});

function buildGraph() {
  return new StateGraph(SpikeState)
    .addNode("ask", async (s) => {
      // Mirrors interruptQuestionNode: interrupt() returns the resume value.
      const answer = interrupt({ type: "question", q: "What is your name?" });
      return { count: s.count + 1, log: [`answer:${answer}`] };
    })
    .addEdge("__start__", "ask")
    .addEdge("ask", "__end__")
    .compile({ checkpointer: new MemorySaver() });
}

export default {
  async fetch(): Promise<Response> {
    try {
      const graph = buildGraph();
      const cfg = { configurable: { thread_id: "spike-1" } };

      // 1) First run -> should pause at the interrupt and surface its payload.
      const first = await graph.invoke({ count: 0 }, cfg);

      // 2) Resume with an answer -> graph completes.
      const resumed = await graph.invoke(new Command({ resume: "Ben" }), cfg);

      return Response.json({
        ok: true,
        interruptedWith: (first as any).__interrupt__ ?? null,
        finalState: resumed,
      });
    } catch (e: any) {
      return Response.json(
        { ok: false, error: String(e?.stack ?? e) },
        { status: 500 },
      );
    }
  },
};
